sect1.example:
    Trait को उदाहरण


<?php

trait TraitA {
    public function sayHello() {
        echo 'Hello';
    }
}

trait TraitB {
    public function sayWorld() {
        echo 'World';
    }
}

class MyHelloWorld
{
    use TraitA, TraitB; // A class can use multiple traits

    public function sayHelloWorld() {
        $this->sayHello();
        echo ' ';
        $this->sayWorld();
        echo "!\n";
    }
}

$myHelloWorld = new MyHelloWorld();
$myHelloWorld->sayHelloWorld();

?>


    &example.outputs;


Hello World!

sect2.example:
    Precedence क्रमको उदाहरण


     Base class बाट inherit गरिएको method लाई SayWorld Trait बाट MyHelloWorld मा
     समावेश गरिएको method ले override गर्दछ। MyHelloWorld class मा परिभाषित methods का
     लागि पनि व्यवहार उस्तै हुन्छ। Precedence को क्रम अनुसार हालको class का methods ले
     Trait methods लाई override गर्दछन्, र ती Trait methods ले base class का methods लाई
     override गर्दछन्।



<?php
class Base {
    public function sayHello() {
        echo 'Hello ';
    }
}

trait SayWorld {
    public function sayHello() {
        parent::sayHello();
        echo 'World!';
    }
}

class MyHelloWorld extends Base {
    use SayWorld;
}

$o = new MyHelloWorld();
$o->sayHello();
?>


    &example.outputs;


Hello World!

    वैकल्पिक Precedence क्रमको उदाहरण


<?php
trait HelloWorld {
    public function sayHello() {
        echo 'Hello World!';
    }
}

class TheWorldIsNotEnough {
    use HelloWorld;
    public function sayHello() {
        echo 'Hello Universe!';
    }
}

$o = new TheWorldIsNotEnough();
$o->sayHello();
?>


    &example.outputs;


Hello Universe!

    Multiple Traits को प्रयोग


<?php
trait Hello {
    public function sayHello() {
        echo 'Hello ';
    }
}

trait World {
    public function sayWorld() {
        echo 'World';
    }
}

class MyHelloWorld {
    use Hello, World;
    public function sayExclamationMark() {
        echo '!';
    }
}

$o = new MyHelloWorld();
$o->sayHello();
$o->sayWorld();
$o->sayExclamationMark();
?>


    &example.outputs;


Hello World!

    Traits बाट बनेका Traits


<?php
trait Hello {
    public function sayHello() {
        echo 'Hello ';
    }
}

trait World {
    public function sayWorld() {
        echo 'World!';
    }
}

trait HelloWorld {
    use Hello, World;
}

class MyHelloWorld {
    use HelloWorld;
}

$o = new MyHelloWorld();
$o->sayHello();
$o->sayWorld();
?>


    &example.outputs;


Hello World!

    Static Variables


<?php

trait Counter
{
    public function inc()
    {
        static $c = 0;
        $c = $c + 1;
        echo "$c\n";
    }
}

class C1
{
    use Counter;
}

class C2
{
    use Counter;
}

$o = new C1();
$o->inc();
$p = new C2();
$p->inc();

?>


    &example.outputs;


1
